/usr/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
import re
ips={}
for n in range(1,61):
 p=Path(f'pc{n}.startup'); s=p.read_text(); ips[n]=re.search(r\"inet (\\d+\\.\\d+\\.\\d+\\.\\d+)/\\d+\",s).group(1)
roles={'com':3,'net':4,'edu':5,'it':6,'org':8,'io':9,'gov':10,'info':12}
records={'shop.example.com':16,'blog.example.com':17,'dept.company.com':18,'intranet.company.com':19,'api.service.com':20,'ai.research.lab.net':22,'data.research.lab.net':23,'dev.lab.net':24,'ci.tools.net':25,'vpn.university.edu':26,'courses.university.edu':27,'portal.campus.edu':28,'studenti.unibo.it':29,'servizi.comune.it':30,'dati.regione.it':31,'archive.foundation.org':42,'docs.project.org':43,'api.startup.io':44,'status.platform.io':45,'open.ministero.gov':46,'servizi.ministero.gov':47,'local.news.info':48,'media.news.info':49,'mail.company.com':7,'mail.dept.company.com':18,'mail.university.edu':11,'mail.servizi.ministero.gov':47}
mx={'company.com':'mail.company.com','dept.company.com':'mail.dept.company.com','university.edu':'mail.university.edu','servizi.ministero.gov':'mail.servizi.ministero.gov'}
def put(n,name,data):
 p=Path(f'pc{n}/etc/bind')/name; p.parent.mkdir(parents=True,exist_ok=True); assert not p.exists(),p; p.write_text(data)
auth='options { directory \"/var/cache/bind\"; recursion no; allow-query { any; }; dnssec-validation no; listen-on { any; }; listen-on-v6 { none; }; };\\n'
put(1,'named.conf',auth+'zone \".\" { type master; file \"/etc/bind/db.root\"; };\\n')
root='"'$TTL 3600'"\\n@ IN SOA a.root-servers. hostmaster.root-servers. ( 1 3600 900 604800 300 )\\n@ IN NS a.root-servers.\\na.root-servers. IN A '+ips[1]+'\\n'
for zone,n in roles.items(): root+=f'{zone}. IN NS ns.{zone}.\\nns.{zone}. IN A {ips[n]}\\n'
put(1,'db.root',root)
for zone,n in roles.items():
 put(n,'named.conf',auth+f'zone \"{zone}\" {{ type master; file \"/etc/bind/db.{zone}\"; }};\\n')
 data=f'"'$TTL 3600'"\\n@ IN SOA ns.{zone}. hostmaster.{zone}. ( 1 3600 900 604800 300 )\\n@ IN NS ns.{zone}.\\nns IN A {ips[n]}\\n'
 for name,pc in records.items():
  if name.endswith('.'+zone): data+=f'{name}. IN A {ips[pc]}\\n'
 for name,target in mx.items():
  if name.endswith('.'+zone): data+=f'{name}. IN MX 10 {target}.\\n'
 put(n,'db.'+zone,data)
put(2,'named.conf','options { directory \"/var/cache/bind\"; recursion yes; allow-recursion { any; }; allow-query { any; }; dnssec-validation no; listen-on { any; }; listen-on-v6 { none; }; };\\nzone \".\" { type hint; file \"/etc/bind/db.hints\"; };\\n')
put(2,'db.hints',f'. 3600000 IN NS a.root-servers.\\na.root-servers. 3600000 IN A {ips[1]}\\n')
servers={1,2,*roles.values()}
for n in range(1,61):
 p=Path(f'pc{n}.startup')
 with p.open('a') as f:
  f.write(f'\\n# DNS del laboratorio\\necho \"nameserver {ips[2]}\" > /etc/resolv.conf\\n')
  if n in servers: f.write('systemctl restart named\\n')
PY"

